/// <summary>
/// Continuing permission notice data provider
/// Class <c>METContinuingPermissionNoticeDP</c> data provider
/// </summary>
[SRSReportParameterAttribute(classstr(METContinuingPermissionNoticeContract))]
class METContinuingPermissionNoticeDP extends SrsReportDataProviderBase
{

    // All of this is pending requirements/clarification of datasources.
    // Most recent note from functional was that this report may not be required at all.

    METContinuingPermissionNoticeHeaderTmp  header;
    METContinuingPermissionNoticeLineTmp    line;
    RecId                                   shipmentId;
    METShipmentTable                        shipmentTable;

}

Method.Source:
    /// <summary>
    /// Process report
    /// </summary>
    public void processReport()
    {
        METContinuingPermissionNoticeContract contract = this.parmDataContract() as METContinuingPermissionNoticeContract;
        shipmentId = contract.parmshipmentId();
        
        select firstonly RecId from shipmentTable
            where shipmentTable.RecId == shipmentId;

        if(shipmentTable.RecId)
        {
            this.insertHeaderData(shipmentTable);
        }
    }

    /// <summary>
    /// Insert Header data
    /// </summary>
    /// <param name = "_shipmentTable">_shipmentTable</param>
    public void insertHeaderData(METShipmentTable  _shipmentTable)
    {
        METShipmentLine                     metShipmentLine;
        SalesTable                          salesTable;
        InventSite                          inventSite;
        InventLocation                      inventLocation;
        LogisticsEntityPostalAddressView    postalAddress;
        CustTable                           custTable;
        DirPartyTable                       dirpartyTable;
        DirPartyLocation                    dirPartyLocation;
        DirPartyPostalAddressView           dirpartyPostaAddressView;
        
        METIndustryKeyTable                 industryKey     = METIndustryKeyTable::find(METCustTable::find(_shipmentTable.CustAccount).IndustryKey);
        METCustTable                        metCustTable    = METCustTable::find(_shipmentTable.CustAccount);
        Image                               img             = CustTable::metGetCustReportLogo(_shipmentTable.CustAccount);
        
        if(img)
        {
            header.CompanyLogo      = img.getData();
        }
        
        if (industryKey)
        {
            header.CompanyName      = industryKey.CompanyName;
            header.SendingBranchABN = industryKey.CoRegNum;
        }

        select firstonly ShipmentId from metShipmentLine
            where metShipmentLine.ShipmentId == _shipmentTable.ShipmentId
                join  SalesId, InventSiteId, InvoiceAccount from salesTable
                    where salesTable.SalesId == metShipmentLine.SalesId
                        join SiteId, RecId, METBondNumber from inventSite
                            where inventSite.SiteId == salesTable.InventSiteId
                                join InventSiteId, Name from inventLocation
                                    where inventLocation.InventSiteId == inventSite.SiteId
                                        join LocationName, Address, EntityType, IsPrimary, Entity from postalAddress
                                            where postalAddress.EntityType == LogisticsLocationEntityType::Warehouse
                                                && postalAddress.IsPrimary == NoYes::Yes
                                                && postalAddress.Entity == inventLocation.RecId;

        header.SendingBranchName                = inventLocation.Name;
        header.SendingBranchAddress             = postalAddress.Address;
        header.SendingBranchBondNumber          = inventSite.METBondNumber;
        header.ContinuingPermissionNoticeNumber = _shipmentTable.ShipmentId;
        header.NoticeDate                       = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        header.NoticeTimeString                 = time2str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()), TimeSeparator::Colon, TimeFormat::Hour24);

        custTable           = CustTable::find(_shipmentTable.CustAccount);
        dirpartyTable       = DirpartyTable::findRec(custTable.Party);
        dirPartyLocation    = DirPartyLocation::findPrimaryPartyLocation(dirpartyTable.RecId);

        header.ReceivingBranchName      = dirpartyTable.Name;

        select firstonly Party, Location, Address, LocationName from dirpartyPostaAddressView
            where dirpartyPostaAddressView.Party == dirPartyLocation.Party
                && dirpartyPostaAddressView.Location == dirPartyLocation.Location;

        if (dirpartyPostaAddressView)
        {
            header.ReceivingBranchAddress   = dirpartyPostaAddressView.Address;
        }
        header.ReceivingBranchBondNumber    = metCustTable.BondNumber;
        header.ReceivingBranchExciseNumber  = metCustTable.ExciseNumber;

        this.insertLineData(_shipmentTable);

        header.insert();

    }

    /// <summary>
    /// Insert Line Data
    /// </summary>
    /// <param name = "_ShipmentTableLine">_ShipmentTableLine</param>
    public void insertLineData(METShipmentTable  _ShipmentTableLine)
    {
        METExciseRegisterEntry  metExciseRegisterEntry;
        METShipmentLine         metShipmentLine;
        Query                   query = new  Query();
        QueryBuildDataSource    queryBuildmetExciseRegisterEntry, queryBuildmetShipmentLine;
        QueryBuildRange         queryBuildRangeShipmentLine, queryBuildRangeExciseRegisterEntry;
        QueryRun                queryRun;

        queryBuildmetShipmentLine           = query.addDataSource(tableNum(METShipmentLine));
        queryBuildRangeShipmentLine         = queryBuildmetShipmentLine.addRange(fieldNum(METShipmentLine, ShipmentId));
        queryBuildRangeShipmentLine.value(_ShipmentTableLine.ShipmentId);
        queryBuildmetExciseRegisterEntry    = queryBuildmetShipmentLine.addDataSource(tableNum(METExciseRegisterEntry));
        queryBuildRangeExciseRegisterEntry  = queryBuildmetExciseRegisterEntry.addRange(fieldNum(METExciseRegisterEntry, OriginType));
        queryBuildRangeExciseRegisterEntry.value(enum2Str(METOriginType::SalesOrder));
        queryBuildmetExciseRegisterEntry.relations(false);
        queryBuildmetExciseRegisterEntry.addLink(fieldNum(METShipmentLine, SalesId),fieldNum(METExciseRegisterEntry, OriginNumber));
        queryBuildmetExciseRegisterEntry.joinMode(JoinMode::InnerJoin);

        queryRun    = new QueryRun(query);

        while(queryRun.next())
        {
            metExciseRegisterEntry  = queryRun.get(tableNum(METExciseRegisterEntry));
            metShipmentLine         = queryRun.get(tableNum(METShipmentLine));
            
            line.BondMark           = metExciseRegisterEntry.Lodgement;
            line.ItemId             = metExciseRegisterEntry.ItemId;
            line.ItemDescription    = EcoResProductTranslation::findByProductLanguage(InventTable::find(line.ItemId).Product, SystemParameters::getSystemLanguageId()).Name;
            
            METInventTable          metInventTable = METInventTable::find(line.ItemId);
            SalesLine               salesLine = SalesLine::find(metShipmentLine.SalesId);
            UnitOfMeasureConversion     unitOfMeasureConversion;

            line.BottleSize                 = metInventTable.ItemSize;
            
            unitOfMeasureConversion         = UnitOfMeasureConversion::findByConversion(
                                                UnitOfMeasure::findBySymbol(salesLine.SalesUnit).RecId,
                                                UnitOfMeasure::findBySymbol(METConstants::unitEach).RecId,
                                                EcoResProduct::findByProductNumber(salesLine.ItemId).RecId);
            if (unitOfMeasureConversion)
            {
                line.PackQty = unitOfMeasureConversion.Factor;
            }
            else
            {
                line.PackQty = 1;
            }

            line.BottlesSupplied            = metExciseRegisterEntry.Quantity;
            line.Strength                   = metInventTable.AlcoholContent;
            line.LitresOfAlcoholCalculated  = metExciseRegisterEntry.LitresOfAlcoholCalculated;
            line.ValueTIU                   = metExciseRegisterEntry.TIUV;
            line.TariffItem                 = metExciseRegisterEntry.TariffItemCode;
            line.CountryOfOrigin            = metExciseRegisterEntry.DutyOriginCountryCode;
            line.StatCode                   = metExciseRegisterEntry.StatCode;
            line.ValueDuty                  = metExciseRegisterEntry.DutyRateReceived;

            SalesTable          salesTable      = SalesTable::find(metShipmentLine.SalesId);
            CustInvoiceJour     custInvoiceJour = CustInvoiceJour::findFromSalesId(salesTable.SalesId);

            line.SalesId                    = salesTable.SalesId;
            line.InvoiceAccount             = custInvoiceJour.InvoiceId;
            line.InvoiceDateTime            = custInvoiceJour.InvoiceDate;

            line.insert();
        }
    }

/// <summary>
/// dsHeader
/// </summary>
/// <returns>METContinuingPermissionNoticeHeaderTmp</returns>
[SrsReportDataSet(tableStr(METContinuingPermissionNoticeHeaderTmp))]
public METContinuingPermissionNoticeHeaderTmp dsHeader()
{
    select header;
    return header;
}

/// <summary>
/// dsLines
/// </summary>
/// <returns>METContinuingPermissionNoticeLineTmp</returns>
[SRSReportDataSet(tableStr(METContinuingPermissionNoticeLineTmp))]
public METContinuingPermissionNoticeLineTmp dsLines()
{
    select line;
    return line;
}
